document.addEventListener('keydown',e=>{const dialog=$('.modal');if(e.key==='Tab'&&dialog){const focusable=[...dialog.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]):not([type=hidden]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(el=>el.getClientRects().length);if(focusable.length){const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){e.preventDefault();first.focus();}}}if(e.key==='Escape'&&dialog)closeModal();if(!dialog&&e.key==='?'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.target.closest('input,textarea,select,[contenteditable=true]')){e.preventDefault();shortcutsModal();return;}if(!dialog&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(state.page!=='map')navigate('map');if(innerWidth<=800&&state.mobile==='map')document.querySelector('[data-mobile=list]')?.click();$('#search')?.focus();}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-card]')){e.preventDefault();selectReport(e.target.dataset.card);}});
