document.addEventListener('input',e=>{if(e.target.closest('#report-form')){updateReportChecklist();if(e.target.name==='category')updateCategoryHint();const review=$('#report-review');if(review)review.hidden=true;}if(e.target.closest('#report-form')&&e.target.name!=='photo')saveDraft();if((e.target.name==='lat'||e.target.name==='lng')&&pickerMarker){const lat=Number($('[name=lat]')?.value),lng=Number($('[name=lng]')?.value);if(Number.isFinite(lat)&&Number.isFinite(lng)&&lat>=33&&lat<=39&&lng>=124&&lng<=132){pickerMarker.setLngLat([lng,lat]);pickerMap?.jumpTo({center:[lng,lat]});}}if(e.target.id==='search'){state.search=e.target.value;updateList();}if(e.target.name==='photo'){delete e.target.form.dataset.uploadedUrl;const input=e.target,file=input.files[0],preview=$('#photo-preview'),sequence=++photoReadSequence;if(!preview)return;preview.classList.add('hidden');preview.removeAttribute('src');if(!file)return;if(!imageTypes.includes(file.type)||file.size>IMAGE_LIMIT){input.value='';toast('5MB 이하의 PNG, JPG, GIF, WebP 또는 AVIF 이미지를 선택해 주세요.');return;}const reader=new FileReader();reader.onload=()=>{if(!input.isConnected||sequence!==photoReadSequence||!input.files.length||$('#photo-preview')!==preview)return;preview.src=reader.result;preview.classList.remove('hidden');};reader.onerror=()=>{if(input.isConnected&&sequence===photoReadSequence&&input.files.length){input.value='';toast('사진을 읽지 못했어요. 다시 선택해 주세요.');}};reader.readAsDataURL(file);}});
