async function checkProfile(){const form=$('#name-form');if(!form||!form.dataset.uncertain)return;const status=$('#name-api-status'),button=form.querySelector('[data-action=check-profile]');button.disabled=true;try{const items=await listAllItems(collections.profiles),found=items.find(item=>item.data?.operationId===form.dataset.operationId&&item.data?.clientId===clientId);if(found){profileItem=found;data.guest=String(found.data.name);closeModal();render();toast('저장된 표시명을 확인했어요.');}else{profileItem=items.find(item=>item.data?.clientId===clientId)||null;delete form.dataset.uncertain;form.querySelector('[type=submit]').disabled=false;button.hidden=true;status.textContent='저장된 표시명을 찾지 못했습니다. 확인 후 직접 다시 저장할 수 있습니다.';}}catch(error){status.textContent='저장 여부를 확인하지 못했습니다: '+apiError(error);}finally{if(button.isConnected)button.disabled=false;}}
